import{_ as l,b as v,c as i,d as a,t as c,C as o,u as n}from"./index-I5uTs6b4.js";const p={class:"level-page"},f={class:"level-content"},u={class:"level-title"},r={__name:"Level10",props:{id:{type:String,required:!0}},setup(e){const d=n();function s(){sessionStorage.setItem("skipIntro","1"),d.push("/")}return(h,t)=>(v(),i("div",p,[a("button",{class:"back-btn",onClick:s},"← Back to Index"),a("div",f,[a("h1",u,"SI-"+c(e.id),1),t[0]||(t[0]=o('<p class="level-name" data-v-25aa0fde>&quot;出塞&quot;</p><div class="section" data-v-25aa0fde><h2 data-v-25aa0fde>生存难度：等级 2</h2><div class="difficulty" data-v-25aa0fde><ul class="class-list" data-v-25aa0fde><li data-v-25aa0fde><span class="class-bullet unsafe" data-v-25aa0fde></span> 不安全</li><li data-v-25aa0fde><span class="class-bullet stable" data-v-25aa0fde></span> 稳定</li><li data-v-25aa0fde><span class="class-bullet entity" data-v-25aa0fde></span> 少量实体</li></ul></div></div><div class="section" data-v-25aa0fde><h2 data-v-25aa0fde>描述</h2><p data-v-25aa0fde>该层级表现为一片沙漠和一座关隘。</p><p data-v-25aa0fde>关隘主要由内城、瓮城、罗城、外城和城壕组成。其核心是方形的内城，东西两侧各有一道瓮城拱卫，形成&quot;回&quot;字形的多重防御格局，易守难攻。沿着那光滑的石板路穿过厚重的拱券式门洞即可进入城内。城内面积开阔，但建筑毫无冗余的装饰，一切都为战争服务。</p><p data-v-25aa0fde>位于内城东北部有一座将军府，这是一座典型的明清院落建筑。其内部陈设着古旧的桌椅、兵器和文书。城中是演武场，是一片开阔的空地，时不时有演员似的士兵办好妆造进行演武，这些演员并非人类，他们没有五官的脸画着脸谱，不知为何，你能透过脸部读出他们的喜怒哀愁。演武场中竖着一把巨大的关刀，你用尽办法也不可能将他拿起。而这关刀的主人却不曾出现。</p><p data-v-25aa0fde>沿着马道可以登上高达 10 余米的城墙。城墙顶部宽阔，外侧有着锯齿形用于瞭望和攻击的垛口。在内城外，建有关帝庙和一座精美的戏台，为这座大漠要塞增添了一丝人间烟火气。</p><p data-v-25aa0fde>出关吧，在城中寻得关照，在西侧寻得掌握官印的&quot;演员&quot;盖上官印即可出关。向西行，穿过戈壁，就能见到那雄伟无比的沙丘。沙丘连绵，那似乎并不能称为&quot;沙丘&quot;，而是由金色流沙堆积而成的沙山。在清晨，阳光为这山镀上一层浓郁的金，明暗交错的线条充满着独属于大地的生命。日落时分的夕阳将整个沙海染成赤金，温度渐降。时不时有驼铃声越过沙丘，可当你望去，那里空无一物，唯有鸣沙作响。</p><p data-v-25aa0fde>你倾听那沙声，能听到那时间所养育沙海之下，埋没这不属于这里的历史与文明。而流浪者们，漫步于其上。</p></div><div class="section" data-v-25aa0fde><h2 data-v-25aa0fde>实体</h2><div class="entity-box" data-v-25aa0fde><p class="entity-name" data-v-25aa0fde>&quot;演员&quot;</p><p data-v-25aa0fde>一群披甲执锐的没有五官的人形实体，面部画有各式脸谱。对流浪者没有攻击性，若流浪者观看他们演武，这些实体会很开心。</p></div></div><div class="section" data-v-25aa0fde><h2 data-v-25aa0fde>入口与出口</h2><h3 class="sub-heading" data-v-25aa0fde>切入点</h3><p data-v-25aa0fde>在有沙漠的层级中存在切入点。切入后流浪者将进入内城外的石板路上。</p><h3 class="sub-heading" data-v-25aa0fde>切出点</h3><p data-v-25aa0fde>在城中找到关照并在出关处加盖官印后向西行走，若是在沙山中寻得清泉即可切出至其他层级。</p></div>',5))])]))}},b=l(r,[["__scopeId","data-v-25aa0fde"]]);export{b as default};
